package com.dxc.dxc_platform.repository; import com.dxc.dxc_platform.entity.Task; import org.springframework.data.jpa.repository.JpaRepository; import java.util.List; public interface TaskRepository extends JpaRepository<Task, Long> { List<Task> findAllByProjectIdAndDeletedFalse(Long projectId); List<Task> findAllByAssignedToIdAndDeletedFalse(Long userId); List<Task> findAllByAssignedToIdAndProjectTeamIdAndDeletedFalse(Long userId, Long teamId); }